mapper.select:
SELECT 
  FROM emp06_family
  JOIN emp01_person ON emp06_person_id = emp01_person_id
 WHERE emp01_company_id = #{companyId}
   AND emp06_person_id  = #{personId}

mapper.insert:
INSERT INTO emp06_family
       ( emp06_family_id, emp06_person_id, emp06_family_nm, emp06_relation_cd
       , emp06_locate_cd, emp06_disability_grade, emp06_birthday
       , emp06_family_school, emp06_family_job, emp06_school_location
       , emp06_family_location, emp06_note )
VALUES ( #{familyId}, #{req.personId}, #{req.familyNm}, #{req.relationCd}
       , #{req.locateCd}, #{req.disabilityGrade}, #{req.birthday}
       , #{req.familySchool}, #{req.familyJob}, #{req.schoolLocation}
       , #{req.familyLocation}, #{req.note} )

mapper.update:
UPDATE emp06_family
   SET emp06_family_nm      = #{req.familyNm}
     , emp06_relation_cd    = #{req.relationCd}
     , emp06_locate_cd      = #{req.locateCd}
     , emp06_disability_grade = #{req.disabilityGrade}
     , emp06_birthday       = #{req.birthday}
     , emp06_family_school  = #{req.familySchool}
     , emp06_family_job     = #{req.familyJob}
     , emp06_school_location = #{req.schoolLocation}
     , emp06_family_location = #{req.familyLocation}
     , emp06_note           = #{req.note}
 WHERE emp06_family_id = #{familyId}
   AND emp06_person_id IN (
       SELECT emp01_person_id FROM emp01_person WHERE emp01_company_id = #{companyId}
   )

